\begin{corollary}
\label{ch02-cor-neckpinch-Lmin}
\source{chow-knopf-ricci-flow:page-0058}
\dcref{Corollary 2.26}
\group{neckpinch}

The minimum of \(L\) is nondecreasing; if \(L_{\min}(0)\neq 0\), then
\[
L_{\min}(t)\ge \frac{1}{L_{\min}^{-1}(0)-2(n-1)t}.
\]
\end{corollary}

